    private static func rings(_ coordinates: [[Double]]) -> [[GeoPoint]] {
        coordinates.map { ring in
            stride(from: 0, to: ring.count, by: 2).map { GeoPoint(latitude: ring[$0], longitude: ring[$0 + 1]) }
        }
    }

